#!/bin/zsh
cd /Users/sina/Developer/Pause/.claude/ws-storm-hazlm
D=/Users/sina/Developer/Pause/.claude/ws-storm-hazlm/Pause/Assets/Art/Worlds/Storm/backdrop_v4~/restyle_landmarks/src~; R=/Users/sina/Developer/Pause/.claude/ws-storm-hazlm/Pause/Assets/Art/Worlds/Storm/backdrop_v4~/restyle_landmarks
REFS=($R/refs/s1_supercell.png $R/refs/new_storm_weather.png $R/refs/ember_landmarks.png $R/refs/verdant_landmarks.png $R/refs/OLD_storm_landmarks_do_not_copy.png)
job() { n=$1; b=$2
  [ -f $D/$n.png ] && return
  { cat $D/common.md; echo; echo "$b"; echo; echo "Output: write the final PNG to $D/$n.png"; } > $D/prompt_$n.md
  zsh scripts/codex-art.sh $PWD $D/prompt_$n.md $D/$n.lastmsg.txt ${REFS[@]} > $D/$n.log 2>&1
  echo "$n exit $? $(ls $D/$n.png 2>&1|tail -1|cut -c1-20)" >> $D/progress.txt
}
job lm_anvils "LANDMARK SHEET 1 (2x2 grid, 4 cells): four different towering ANVIL THUNDERHEAD storm cells, each seen in an oblique aerial three-quarter view from above, standing as huge solitary storm towers rising from the cloud sea. They must read as real cumulonimbus: a tall churning convective column with an overshooting dome, a wide sheared anvil spreading out at the top and streaming downwind, hard lit tops and deep shadowed undersides, soft noisy irregular edges, lightning flickering INSIDE the cloud mass (cool white and pale violet-white glow through the cloud), and a dark shaft of rain falling from the base. Each one different: (1) a classic tall anvil leaning right with a long sheared spread, (2) a cluster of overshooting domes merging into a lopsided broken anvil, (3) a narrow very tall tower with a torn thin anvil and a strike glowing deep inside, (4) a squat wide shelf-cloud thunderhead with mammatus pouches under the anvil and heavy rain curtains. Asymmetric, NOT mushroom shaped, NOT symmetric, NOT lumpy blobs."
job lm_masts "LANDMARK SHEET 2 (2x2 grid, 4 cells): cells 1-2: two different LIGHTNING-ROD MASTS: tall slender weathered dark steel lattice masts on a small floating platform, with a pale violet-white corona glowing at the tip (St Elmo's fire), guy wires, a few small lit windows (pale cool white) and storm wear; different heights and shapes. Cells 3-4: two different SKYHOOK anchors: a large floating balloon-borne mooring anchor with a heavy steel hook and cables dangling, lit by a few cool white lamps, one with three envelopes and one with a single big envelope; weathered, asymmetric. Oblique aerial three-quarter view from above. Cool steel and slate metal, no orange or brass."
job lm_refineries "LANDMARK SHEET 3 (2x2 grid, 4 cells): cells 1-3: three different FLOATING REFINERIES, aerial three-quarter view from above: weathered steel platforms held up by cloud-borne buoyancy tanks with processing towers, pipe racks, stacks venting pale steam that tears off downwind, a few small cool-white lamps, rivets, panel seams; different layouts (one tall stacked, one long and low, one with a flare stack, flame drawn pale blue-white). Cell 4: a SIPHON TOWER: a tall slim spiral intake tower drawing storm air, with a ring of intake vanes and a trailing vapour wisp. Cool steel, slate, teal-grey, no orange or brass or rust."
job lm_docks "LANDMARK SHEET 4 (2x2 grid, 4 cells): four different storm-world structures floating in the clouds, aerial three-quarter view from above, believable weathered cool steel: (1) an AIRSHIP DOCK: a mooring platform with a moored slim airship lit by cool white lamps; (2) a GANTRY: a tall industrial crane gantry on a floating platform with a hanging cable and hook; (3) a TURBINE RAFT: a floating raft carrying three big wind turbines (blades visible, still); (4) a RELAY DISH: a large radar or relay dish on a lattice mast with a pale blinking lamp. Asymmetric, detailed, not cartoony."
job hz_swirl "TORNADO VORTEX (single element, centred, filling about 90 percent of the square): a realistic TOP-DOWN view of a violent tornado or cyclone vortex seen from straight above: a dark calm eye in the centre, tight spiral arms of dark storm cloud and wind-torn debris spiralling in, ragged soft noisy outer arms thinning to transparent at the edge (no hard circle edge, no ring outline), subtle cool white and pale violet-white lightning veins glowing inside the arms, steel-blue and slate colours, volumetric, ~12 percent of arms catching cool pale light. It must be roughly circular and fade to fully transparent before the edge of the image. It will be rotated by the game, so spiral arms must read in any orientation."
job hz_front "SQUALL FRONT TILE (single element): a realistic wide band of gust-front shelf cloud and rain, seen from above at an oblique angle, running horizontally across the WHOLE width of the square: a rolled, ragged dark storm shelf along the upper half with noisy soft edges, rain curtains falling below it, and wind-torn spray. It must tile SEAMLESSLY left to right: the left and right edges of the image must match exactly (the content continues across the edges and nothing is cut off). Vertically, content sits in the middle 60 percent and fades to fully transparent above and below. Colours: slate, steel-blue, dark graphite and white-grey spray; low brightness."
echo ALLDONE >> $D/progress.txt
